import { useState, useRef } from "react";
import { useGSAP } from "../hooks/useGSAP";
import { ParticleCanvas, Typewriter, SkillBar, Modal, ParallaxElement, ScrollReveal } from "../components/Shared";
import { DevBadge } from "../components/DeveloperMode";
import { PROJECTS, SKILLS, TECH, SERVICES, TIMELINE, CONTACT_INFO } from "../data/content";

// ── Interactive Skill Tree Component ───────────────────────────────────────────────────
function InteractiveSkillTree({ theme }) {
  const [selectedSkill, setSelectedSkill] = useState(null);
  const [hoveredSkill, setHoveredSkill] = useState(null);

  const skillCategories = [
    {
      name: "Frontend",
      icon: "🎨",
      skills: ["React", "Vue", "TypeScript", "Tailwind CSS"],
      color: theme.accent
    },
    {
      name: "Backend", 
      icon: "⚙️",
      skills: ["Node.js", "Python", "PostgreSQL", "MongoDB"],
      color: "#10b981"
    },
    {
      name: "Tools",
      icon: "🛠️", 
      skills: ["Git", "Docker", "AWS", "Figma"],
      color: "#f59e0b"
    }
  ];

  return (
    <div style={{ 
      background: `${theme.surface}dd`, 
      border: `1px solid ${theme.border}`,
      borderRadius: 16, 
      padding: 32, 
      maxWidth: 600,
      margin: "0 auto",
      backdropFilter: "blur(10px)",
      boxShadow: theme.shadowMd
    }}>
      <div style={{ textAlign: "center", marginBottom: 24 }}>
        <h3 style={{ 
          fontFamily: "'Syne', sans-serif", 
          fontSize: 18, 
          fontWeight: 700, 
          color: theme.text,
          marginBottom: 8 
        }}>
          Interactive Skill Tree
        </h3>
        <p style={{ 
          fontSize: 13, 
          color: theme.textMuted, 
          lineHeight: 1.6 
        }}>
          Click on any skill category to explore my expertise
        </p>
      </div>

      <div style={{ 
        display: "grid", 
        gridTemplateColumns: "repeat(auto-fit, minmax(160px, 1fr))", 
        gap: 16,
        marginBottom: 24 
      }}>
        {skillCategories.map((category, index) => (
          <button
            key={category.name}
            onClick={() => setSelectedSkill(selectedSkill === category.name ? null : category.name)}
            onMouseEnter={() => setHoveredSkill(category.name)}
            onMouseLeave={() => setHoveredSkill(null)}
            style={{
              background: selectedSkill === category.name ? category.color : theme.surface,
              border: `2px solid ${category.color}`,
              borderRadius: 12,
              padding: 16,
              cursor: "pointer",
              transition: "all 0.3s ease",
              transform: hoveredSkill === category.name ? "translateY(-2px)" : "translateY(0)",
              boxShadow: hoveredSkill === category.name ? theme.shadowMd : theme.shadow
            }}
          >
            <div style={{ fontSize: 24, marginBottom: 8 }}>{category.icon}</div>
            <div style={{ 
              fontFamily: "'Space Mono', monospace", 
              fontSize: 12, 
              fontWeight: 600,
              color: selectedSkill === category.name ? "#fff" : category.color 
            }}>
              {category.name}
            </div>
          </button>
        ))}
      </div>

      {selectedSkill && (
        <div style={{
          background: theme.bgAlt,
          border: `1px solid ${theme.border}`,
          borderRadius: 8,
          padding: 16,
          animation: "fadeIn 0.3s ease"
        }}>
          <div style={{ 
            display: "flex", 
            flexWrap: "wrap", 
            gap: 8,
            justifyContent: "center"
          }}>
            {skillCategories.find(cat => cat.name === selectedSkill)?.skills.map(skill => (
              <span
                key={skill}
                style={{
                  background: theme.surface,
                  border: `1px solid ${theme.border}`,
                  borderRadius: 6,
                  padding: "6px 12px",
                  fontSize: 11,
                  fontFamily: "'Space Mono', monospace",
                  color: theme.text,
                  transition: "all 0.2s ease"
                }}
              >
                {skill}
              </span>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}
function ProjectCard({ project, theme, onSelect }) {
  const [hovered, setHovered] = useState(false);
  const [tilt, setTilt] = useState({ x: 0, y: 0 });
  const ref = useRef(null);

  const handleMouseMove = (e) => {
    const rect = ref.current.getBoundingClientRect();
    setTilt({
      x: ((e.clientY - rect.top - rect.height / 2) / rect.height) * -7,
      y: ((e.clientX - rect.left - rect.width / 2) / rect.width) * 7
    });
  };

  return (
    <div 
      ref={ref} 
      onMouseEnter={() => setHovered(true)} 
      onMouseLeave={() => { setHovered(false); setTilt({ x: 0, y: 0 }); }} 
      onMouseMove={handleMouseMove} 
      onClick={() => onSelect(project)} 
      style={{
        width: "100%",
        maxWidth: 450,
        flexShrink: 0,
        background: hovered ? theme.surface : theme.surfaceAlt,
        border: `1px solid ${hovered ? theme.borderMid : theme.border}`,
        borderRadius: "18px 4px 18px 4px",
        overflow: "hidden",
        cursor: "pointer",
        transform: hovered 
          ? `perspective(700px) rotateX(${tilt.x}deg) rotateY(${tilt.y}deg) translateY(-5px)` 
          : "perspective(700px) rotateX(0) rotateY(0)",
        transition: "all .3s",
        boxShadow: hovered ? theme.shadowMd : theme.shadow,
        backdropFilter: "blur(12px)"
      }}
    >
      <div style={{ height: 148, background: project.cardBg, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 46 }}>
        {project.emoji}
      </div>
      <div style={{ padding: "15px 20px 22px" }}>
